    'legal.accuracy': 'Exactitude des informations',
    'legal.accuracyDesc': 'InfoEau.fr s\'efforce de fournir des informations exactes et à jour. Cependant, nous ne pouvons garantir l\'exactitude, la complétude ou l\'actualité des informations diffusées sur le site. Les données sont issues de sources officielles mais peuvent comporter des erreurs ou des retards.',
    'legal.limitation': 'Limitation de responsabilité',
    'legal.limitationDesc': 'L\'utilisation des informations fournies se fait sous la seule responsabilité de l\'utilisateur. InfoEau.fr ne saurait être tenu responsable de tout dommage direct ou indirect résultant de l\'utilisation des informations du site. En cas de doute sur la qualité de votre eau, consultez les services officiels compétents.',
    'legal.availability': 'Disponibilité du service',
    'legal.availabilityDesc': 'Nous nous efforçons d\'assurer une disponibilité continue du site, mais ne pouvons garantir un accès ininterrompu. Le site peut être temporairement inaccessible pour des raisons de maintenance, de mise à jour ou de défaillance technique.',
    'legal.terms': 'Conditions d\'utilisation',
    'legal.access': 'Accès au site',
    'legal.accessDesc': 'L\'accès au site InfoEau.fr est libre et gratuit. Aucune inscription n\'est requise pour consulter les informations publiques. L\'utilisateur s\'engage à utiliser le site de manière responsable et conforme aux lois en vigueur.',
    'legal.usage': 'Usage autorisé',
    'legal.usageDesc': 'Le site est destiné à un usage personnel et informatif. L\'utilisation commerciale des données ou du contenu du site nécessite une autorisation préalable. Les utilisateurs peuvent partager et citer les informations du site en mentionnant la source.',
    'legal.changes': 'Modification des conditions',
    'legal.changesDesc': 'Ces mentions légales peuvent être modifiées à tout moment sans préavis. Il appartient aux utilisateurs de consulter régulièrement cette page pour prendre connaissance des éventuelles modifications.',
    'legal.law': 'Droit applicable et juridiction',
    'legal.lawDesc': 'Les présentes mentions légales sont régies par le droit français. En cas de litige, et après recherche d\'une solution amiable, les tribunaux français seront seuls compétents. Pour toute question concernant ces mentions légales, vous pouvez nous contacter à l\'adresse : contact@infoeau.fr',

