    'lettre.badge': "Lettre de l'eau",
    'lettre.tagline': "Le magazine d'InfoEau",
    'lettre.h1.part1': "Tout ce qu'il faut savoir sur",
    'lettre.h1.part2': "la qualité de l'eau",
    'lettre.intro': "Enquêtes, scandales, décisions réglementaires, alertes sanitaires : chaque article décrypte une actualité récente sur l'eau en France.",
    'lettre.editorial.p1': "La Lettre de l'eau est le fil éditorial d'InfoEau.fr : une veille indépendante sur la qualité de l'eau potable en France, nourrie par les publications officielles (ARS, Hub'Eau, ANSES), la presse spécialisée et nos propres relevés de terrain.",
    'lettre.editorial.p2': "Chaque semaine, un nouvel article remet une actualité dans son contexte : ce que dit la réglementation, ce que montrent les analyses, et ce que cela change concrètement pour l'eau qui sort de votre robinet.",
