    // Guide Ma Commune
    'guide.commune.seo.title': "Guide « Ma commune » — Qualité de l'eau du robinet, questions clés",
    'guide.commune.seo.description': "Le guide complet pour comprendre l'eau du robinet dans votre commune : potabilité, polluants (PFAS, nitrates, plomb), dureté, goût, filtration. Données officielles Hub'Eau / ARS.",
    'guide.commune.badge': 'Guide pratique',
    'guide.commune.h1': "Ma commune : tout savoir sur l'eau du robinet",
    'guide.commune.intro': "Les 5 questions clés que se posent les Français sur l'eau du robinet — et les réponses avec les données officielles Hub'Eau / ARS pour votre commune.",
    'guide.commune.search.label': 'Rechercher ma commune',
    'guide.commune.search.placeholder': 'Nom de ville ou code postal…',
    'guide.commune.search.empty': 'Aucune commune ne correspond. Consultez la',
    'guide.commune.search.emptyLink': 'liste complète',
    'guide.commune.q.title': 'Les 5 questions clés',
    'guide.commune.q.label': 'Question',
    'guide.commune.q1.q': "L'eau du robinet est-elle potable dans ma commune ?",
    'guide.commune.q1.a': "Oui, dans la quasi-totalité des communes françaises. L'ARS effectue plusieurs prélèvements par an et publie les résultats sur Hub'Eau. La page de votre commune affiche le taux de conformité, le score global et l'écart aux limites réglementaires du Code de la santé publique.",
    'guide.commune.q2.q': 'Quels polluants sont surveillés (PFAS, nitrates, pesticides, plomb) ?',
    'guide.commune.q2.a': "Les analyses officielles couvrent nitrates, pesticides (dont métabolites), PFAS (depuis 2023), métaux lourds (plomb, cuivre, nickel), chlore résiduel, THM et paramètres microbiologiques (E. coli, entérocoques). Chaque paramètre est comparé à sa limite réglementaire — la fiche commune affiche les dépassements éventuels.",
    'guide.commune.q3.q': "Quelle est la dureté (calcaire) de l'eau chez moi ?",
    'guide.commune.q3.a': "La dureté est exprimée en °f (degré français) : <15 °f eau douce, 15-30 °f moyennement dure, >30 °f dure. Elle dépend de la source (nappe calcaire ou eau de surface). La fiche de votre commune affiche la dernière valeur mesurée et son classement.",
    'guide.commune.q4.q': "Pourquoi mon eau a un goût ou une odeur de chlore ?",
    'guide.commune.q4.a': "Le chlore résiduel (0,1 à 0,3 mg/L en sortie de traitement) est obligatoire pour garantir l'absence de bactéries dans le réseau. L'odeur disparaît en laissant l'eau reposer 30 min au réfrigérateur. Consultez aussi la page /gout-eau pour les retours par région.",
    'guide.commune.q5.q': 'Faut-il filtrer son eau ou passer à la bouteille ?',
    'guide.commune.q5.a': "Pour la plupart des communes conformes, ni l'un ni l'autre n'est nécessaire. Un filtre à charbon peut améliorer le goût si le chlore vous dérange. En cas de plomb (canalisation ancienne), laissez couler l'eau 30 s avant usage alimentaire. Un adoucisseur ne se justifie qu'au-delà de 30 °f.",
    'guide.commune.how.title': 'Comment lire la fiche de ma commune',
    'guide.commune.how.score.q': 'Le score global (0-100)',
    'guide.commune.how.score.a': "Calculé sur les 24 derniers mois de prélèvements : conformité, écart aux limites, diversité des polluants détectés. Un score ≥ 80 correspond à une eau d'excellente qualité, 60-80 bonne, 40-60 correcte avec vigilance, < 40 alerte.",
    'guide.commune.how.conf.q': 'La conformité (limite vs référence)',
    'guide.commune.how.conf.a': "Deux seuils existent : limite de qualité (contraignante, risque sanitaire) et référence de qualité (indicative, confort). Un dépassement de référence n'est pas dangereux mais signale un suivi renforcé.",
    'guide.commune.how.date.q': 'La date de prélèvement',
    'guide.commune.how.date.a': "Nous affichons la date réelle du prélèvement terrain (« Prélevé le »), pas la date de publication. L'ARS met en ligne les résultats 4 à 8 semaines après l'analyse laboratoire.",
    'guide.commune.how.params.q': 'Les paramètres surveillés',
    'guide.commune.how.params.a': 'Plus de 60 paramètres au total selon la commune : nitrates, pesticides, PFAS, plomb, cuivre, THM, chlore, pH, turbidité, microbiologie. La fiche affiche ceux effectivement mesurés lors du dernier passage.',
    'guide.commune.cta.title': 'Prêt·e à consulter les données de votre commune ?',
    'guide.commune.cta.body': 'Accédez à la liste complète des communes couvertes ou explorez la carte interactive.',
    'guide.commune.cta.all': 'Voir toutes les communes',
    'guide.commune.cta.map': 'Ouvrir la carte de France',
    'guide.commune.hub.heading': 'Aller plus loin',
    'guide.commune.hub.description': 'Cartes, polluants et guides complémentaires.',

