    // Guide Eaux Magnésium
    'mg.seo.title': 'Eaux riches en magnésium : classement 2026 (Rozana, Hépar…)',
    'mg.seo.description': '10 eaux classées par teneur en magnésium, du plus fort (Rozana 160mg/L) au plus faible. Utile contre fatigue, stress ou crampes : comparatif et conseils.',

    'mg.breadcrumb.guides': 'Guides',
    'mg.breadcrumb.current': 'Eaux riches en magnésium',
    'mg.tag': 'Guide santé · Minéraux',
    'mg.h1.pre': 'Les meilleures',
    'mg.h1.highlight': 'eaux riches en magnésium',
    'mg.intro': "Fatigue, crampes, stress ? Le magnésium est un allié précieux. Nous avons comparé les principales eaux minérales françaises pour identifier celles qui en apportent le plus, avec les précautions à connaître.",
    'mg.stat.count': 'eaux comparées',
    'mg.stat.anses': 'Apports journaliers ANSES',
    'mg.why.title': 'Pourquoi boire une eau riche en magnésium ?',
    'mg.why.p1.a': 'Le magnésium est un minéral',
    'mg.why.p1.b': 'essentiel',
    'mg.why.p1.c': " impliqué dans plus de 300 réactions enzymatiques : production d'énergie, contraction musculaire, transmission nerveuse, régulation du rythme cardiaque. Selon l'étude SU.VI.MAX, près de ",
    'mg.why.p1.d': '75 % des Français',
    'mg.why.p1.e': " ont des apports inférieurs aux recommandations de l'ANSES (380 mg/jour pour un homme, 300 mg/jour pour une femme).",
    'mg.why.p2.a': 'Les eaux minérales sont une source de magnésium ',
    'mg.why.p2.b': 'hautement biodisponible',
    'mg.why.p2.c': " : le corps l'assimile mieux que celui contenu dans certains aliments. Un litre d'Hépar couvre à lui seul près de 40 % des besoins quotidiens.",
    'mg.benefit.fatigue.title': 'Anti-fatigue',
    'mg.benefit.fatigue.text': 'Réduit la fatigue physique et mentale',
    'mg.benefit.heart.title': 'Cœur & muscles',
    'mg.benefit.heart.text': 'Prévient crampes et palpitations',
    'mg.benefit.stress.title': 'Stress & sommeil',
    'mg.benefit.stress.text': 'Favorise la détente nerveuse',
    'mg.table.title': 'Comparatif des eaux les plus riches en magnésium',
    'mg.table.subtitle': 'Classement du plus riche au moins riche. Les valeurs sont issues des étiquettes officielles des embouteilleurs (mg/L).',
    'mg.table.water': 'Eau',
    'mg.table.magnesium': 'Magnésium',
    'mg.table.calcium': 'Calcium',
    'mg.table.sodium': 'Sodium',
    'mg.table.type': 'Type',
    'mg.type.sparkling': 'Gazeuse',
    'mg.type.still': 'Plate',
    'mg.disclaimer.a': 'Une eau est considérée comme ',
    'mg.disclaimer.b': 'riche en magnésium',
    'mg.disclaimer.c': " dès 50 mg/L (règlement européen n° 1924/2006 sur les allégations nutritionnelles).",
    'mg.tips.title': 'Comment bien choisir son eau riche en magnésium ?',
    'mg.tips.1.h': '1. Regardez aussi le sodium',
    'mg.tips.1.p': "Certaines eaux très minéralisées (Saint-Yorre, Vichy Célestins) contiennent plus de 1000 mg/L de sodium — soit près d'un demi-gramme de sel par litre. À éviter en cas d'hypertension.",
    'mg.tips.2.h': '2. Alternez avec une eau faiblement minéralisée',
    'mg.tips.2.p.a': 'Les eaux type ',
    'mg.tips.2.p.b': 'Hépar',
    'mg.tips.2.p.c': ' ou ',
    'mg.tips.2.p.d': 'Contrex',
    'mg.tips.2.p.e': ' sont efficaces en ',
    'mg.tips.2.p.f': 'cure de 1 à 2 semaines',
    'mg.tips.2.p.g': ', en alternance avec une eau plus légère (Volvic, Mont Roucous, Evian) pour un usage quotidien.',
    'mg.tips.3.h': "3. Consultez la qualité de votre eau du robinet",
    'mg.tips.3.p.a': "Avant d'investir dans une eau en bouteille, vérifiez la teneur en minéraux de ",
    'mg.tips.3.p.link': "l'eau du robinet dans votre commune",
    'mg.tips.3.p.b': ' — elle peut déjà couvrir une partie de vos besoins.',
    'mg.faq.title': 'FAQ — Eaux riches en magnésium',
    'mg.faq.q1.q': "Quelle est l'eau la plus riche en magnésium ?",
    'mg.faq.q1.a': "En France, Rozana est l'eau minérale naturelle qui contient le plus de magnésium (environ 160 mg/L), suivie de très près par Hépar (119 mg/L). Ces deux eaux couvrent à elles seules près de 30 % des apports journaliers recommandés (AJR) en magnésium avec un seul litre.",
    'mg.faq.q2.q': 'Combien de magnésium par jour un adulte doit-il consommer ?',
    'mg.faq.q2.a': "L'ANSES recommande 380 mg/jour pour un homme adulte et 300 mg/jour pour une femme adulte. Un litre d'Hépar apporte à lui seul environ 40 % de ces besoins.",
    'mg.faq.q3.q': "Quels sont les bienfaits d'une eau riche en magnésium ?",
    'mg.faq.q3.a': "Le magnésium contribue à réduire la fatigue, au bon fonctionnement du système nerveux et musculaire, à l'équilibre électrolytique et à la synthèse protéique. Boire une eau minéralisée peut compléter les apports alimentaires en cas de stress, de sport intense ou de crampes.",
    'mg.faq.q4.q': 'Peut-on boire tous les jours une eau riche en magnésium ?',
    'mg.faq.q4.a': "Oui, mais avec discernement. Les eaux très minéralisées type Hépar ou Contrex ne sont pas conseillées comme unique boisson : elles sont efficaces en cure ponctuelle (1 à 2 semaines) ou en alternance avec une eau faiblement minéralisée. Les personnes souffrant d'insuffisance rénale ou d'hypertension doivent consulter leur médecin.",
    'mg.faq.q5.q': "Une eau du robinet peut-elle être riche en magnésium ?",
    'mg.faq.q5.a': "La plupart des eaux du robinet contiennent entre 3 et 30 mg/L de magnésium — bien en dessous des eaux minérales. Consultez notre carte pour connaître la teneur exacte dans votre commune.",
    'mg.cta.title': 'Vous ne savez pas quelle eau choisir ?',
    'mg.cta.body': 'Notre outil de recommandation personnalisée vous conseille en fonction de vos besoins (fatigue, sport, grossesse, hypertension...).',
    'mg.cta.button': 'Trouver mon eau idéale',
    'mg.hub.heading': 'Aller plus loin',
    'mg.hub.description': 'Ressources complémentaires pour bien choisir votre eau.',
