    'commune.analysis.intro': 'L\'eau distribuée à {name} ({postcode}, {context}) est surveillée par l\'Agence Régionale de Santé (ARS) via le contrôle sanitaire officiel. Les paramètres analysés couvrent la qualité microbiologique (Escherichia coli, entérocoques), physico-chimique (pH, conductivité, dureté), les nitrates, pesticides, PFAS, métaux lourds (plomb, arsenic, cuivre) et paramètres organoleptiques.',
