    // About page
    'about.title': 'About InfoEau.fr',
    'about.subtitle': 'A citizen initiative to democratize access to information on drinking water quality in France.',
    'about.missionTitle': 'Our mission',
    'about.missionText': 'InfoEau.fr was created with a simple conviction: every French and European citizen has the right to know the quality of their drinking water in a clear, accessible and transparent way. We transform complex official data into understandable information for everyone, in France and in the 27 EU countries.',
    'about.historyTitle': 'Our history',
    'about.historyText1': 'InfoEau.fr was born from a simple observation: despite the existence of public data on water quality, this information remained difficult to access and complex to interpret for the general public. Citizens had to navigate between several institutional sites, decipher technical reports and understand obscure parameter codes.',
    'about.historyText2': 'Created by Nathan Orso, developer and engaged citizen, this project aims to bridge this digital and democratic gap. The goal is to make water information as accessible as weather forecasts, using the same intuitive visual codes and user experience standards.',
    'about.historyText3': 'Today, InfoEau.fr centralizes and visualizes data from over 36,000 French municipalities, offering an unprecedented overview of drinking water quality in France. Our platform continues to evolve thanks to user feedback and community engagement.',
    'about.valuesTitle': 'Our values',
    'about.timelineTitle': 'Timeline',
    'about.impactTitle': 'Our impact',
    'about.joinTitle': 'Join our mission',
    'about.joinText': 'InfoEau.fr is an open citizen project. We welcome contributions, suggestions for improvement and partnerships with stakeholders committed to environmental transparency.',
    'about.contactUs': 'Contact us',
    'about.transparency': 'Transparency',
    'about.transparencyDesc': 'We believe every citizen has the right to know the quality of their drinking water without opacity or biased interpretation.',
    'about.accessibilityValue': 'Accessibility',
    'about.accessibilityDesc': 'Data must be understandable by all, whether experts or citizens concerned about their health.',
    'about.reliability': 'Reliability',
    'about.reliabilityDesc': 'We exclusively use official sources and apply rigorous scientific methods.',
    'about.citizenEngagement': 'Citizen engagement',
    'about.citizenEngagementDesc': 'Our mission is to contribute to a more informed and responsible society regarding the environment.',
    'about.municipalitiesCovered': 'Municipalities covered',
    'about.euCountries': 'EU countries covered',
    'about.officialData': 'Official data',
    'about.freeAccess': 'Free access for all',
