    'legal.publicDataDesc': 'The data presented on the site comes from French public organizations (ARS, EauFrance, BRGM) and European (European Environment Agency – EEA, WISE DWD) and are governed by Open Data principles. European data are subject to the EEA standard reuse policy. This data remains the property of their respective issuing organizations.',
