    'legal.accuracyDesc': 'InfoEau.fr strives to provide accurate and up-to-date information. However, we cannot guarantee the accuracy, completeness or timeliness of information published on the site. Data comes from official sources but may contain errors or delays.',
    'legal.limitation': 'Limitation of liability',
