    // Lettre de l'eau (blog)
    'lettre.badge': "Water Letter",
    'lettre.tagline': "InfoEau's magazine",
    'lettre.h1.part1': 'Everything you need to know about',
    'lettre.h1.part2': 'water quality',
    'lettre.intro': 'Investigations, scandals, regulatory decisions, health alerts: each article deciphers a recent news story about water in France.',
    'lettre.editorial.p1': "The Water Letter is InfoEau.fr's editorial thread: independent monitoring of drinking water quality in France, based on official publications (ARS, Hub'Eau, ANSES), specialist press and our own field data.",
    'lettre.editorial.p2': 'Every week, a new article puts a news story in context: what the regulation says, what the analyses show, and what it actually changes for the water coming out of your tap.',
    'lettre.editorial.p3': 'All articles remain freely available and are sorted by topic: pollutants and contaminants, water prices, regulation, local alerts and in-depth investigations.',
