    // Guide My Town
    'guide.commune.seo.title': 'The "My town" guide — Tap water quality, key questions',
    'guide.commune.seo.description': "The complete guide to understanding tap water in your town: potability, pollutants (PFAS, nitrates, lead), hardness, taste, filtration. Official Hub'Eau / ARS data.",
    'guide.commune.badge': 'Practical guide',
    'guide.commune.h1': 'My town: everything about tap water',
    'guide.commune.intro': "The 5 key questions the French ask about tap water — with answers and the official Hub'Eau / ARS data for your town.",
    'guide.commune.search.label': 'Search my town',
    'guide.commune.search.placeholder': 'Town name or postcode…',
    'guide.commune.search.empty': 'No town matches. See the',
    'guide.commune.search.emptyLink': 'full list',
    'guide.commune.q.title': 'The 5 key questions',
    'guide.commune.q.label': 'Question',
    'guide.commune.q1.q': 'Is tap water drinkable in my town?',
    'guide.commune.q1.a': "Yes, in almost every French town. The ARS carries out several samples per year and publishes results on Hub'Eau. Your town's page shows the compliance rate, overall score and gap to the regulatory limits of the French Public Health Code.",
    'guide.commune.q2.q': 'Which pollutants are monitored (PFAS, nitrates, pesticides, lead)?',
    'guide.commune.q2.a': 'Official analyses cover nitrates, pesticides (including metabolites), PFAS (since 2023), heavy metals (lead, copper, nickel), residual chlorine, THMs and microbiological parameters (E. coli, enterococci). Each parameter is compared to its regulatory limit — the town page displays any exceedances.',
    'guide.commune.q3.q': "What is the hardness (limescale) of the water at my address?",
    'guide.commune.q3.a': 'Hardness is expressed in °f (French degrees): <15 °f soft, 15-30 °f moderately hard, >30 °f hard. It depends on the source (limestone aquifer or surface water). Your town page shows the latest measured value and its class.',
    'guide.commune.q4.q': 'Why does my water taste or smell of chlorine?',
    'guide.commune.q4.a': 'Residual chlorine (0.1 to 0.3 mg/L at treatment outlet) is mandatory to prevent bacteria in the network. The smell disappears if you let the water rest in the fridge for 30 min. See also /gout-eau for regional feedback.',
    'guide.commune.q5.q': 'Should I filter my water or switch to bottled?',
    'guide.commune.q5.a': 'For most compliant towns neither is necessary. A carbon filter can improve taste if chlorine bothers you. If lead is present (old pipes), let the water run for 30 s before food use. A softener is only justified above 30 °f.',
    'guide.commune.how.title': 'How to read your town page',
    'guide.commune.how.score.q': 'The overall score (0-100)',
    'guide.commune.how.score.a': 'Calculated from the last 24 months of samples: compliance, gap to limits, diversity of detected pollutants. A score ≥ 80 is excellent quality, 60-80 good, 40-60 acceptable with caution, < 40 alert.',
    'guide.commune.how.conf.q': 'Compliance (limit vs reference)',
    'guide.commune.how.conf.a': 'Two thresholds exist: quality limit (binding, health risk) and quality reference (indicative, comfort). Exceeding a reference is not dangerous but signals enhanced monitoring.',
    'guide.commune.how.date.q': 'The sampling date',
    'guide.commune.how.date.a': 'We display the actual field sampling date ("Sampled on"), not the publication date. The ARS publishes results 4 to 8 weeks after lab analysis.',
    'guide.commune.how.params.q': 'Monitored parameters',
    'guide.commune.how.params.a': 'More than 60 parameters total depending on the town: nitrates, pesticides, PFAS, lead, copper, THMs, chlorine, pH, turbidity, microbiology. The page shows those actually measured during the latest run.',
    'guide.commune.cta.title': 'Ready to check your town data?',
    'guide.commune.cta.body': 'Access the complete list of covered towns or explore the interactive map.',
    'guide.commune.cta.all': 'See all towns',
    'guide.commune.cta.map': 'Open the France map',
    'guide.commune.hub.heading': 'Go further',
    'guide.commune.hub.description': 'Maps, pollutants and complementary guides.',

