    // Guide Magnesium-Rich Waters
    'mg.seo.title': 'Magnesium-rich waters: 2026 ranking (Rozana, Hépar…)',
    'mg.seo.description': '10 waters ranked by magnesium content, from the strongest (Rozana 160mg/L) to the lowest. Helpful for fatigue, stress or cramps: full comparison and advice.',

    'mg.breadcrumb.guides': 'Guides',
    'mg.breadcrumb.current': 'Magnesium-rich waters',
    'mg.tag': 'Health guide · Minerals',
    'mg.h1.pre': 'The best',
    'mg.h1.highlight': 'magnesium-rich waters',
    'mg.intro': 'Fatigue, cramps, stress? Magnesium is a valuable ally. We compared the main French mineral waters to identify those that provide the most, with the precautions to know.',
    'mg.stat.count': 'waters compared',
    'mg.stat.anses': 'ANSES daily intakes',
    'mg.why.title': 'Why drink magnesium-rich water?',
    'mg.why.p1.a': 'Magnesium is an ',
    'mg.why.p1.b': 'essential',
    'mg.why.p1.c': ' mineral involved in more than 300 enzymatic reactions: energy production, muscle contraction, nerve transmission, heart rhythm regulation. According to the SU.VI.MAX study, nearly ',
    'mg.why.p1.d': '75% of French people',
    'mg.why.p1.e': " have intakes below ANSES recommendations (380 mg/day for a man, 300 mg/day for a woman).",
    'mg.why.p2.a': 'Mineral waters are a ',
    'mg.why.p2.b': 'highly bioavailable',
    'mg.why.p2.c': " source of magnesium: the body absorbs it better than that contained in certain foods. A liter of Hépar alone covers nearly 40% of daily needs.",
    'mg.benefit.fatigue.title': 'Anti-fatigue',
    'mg.benefit.fatigue.text': 'Reduces physical and mental fatigue',
    'mg.benefit.heart.title': 'Heart & muscles',
    'mg.benefit.heart.text': 'Prevents cramps and palpitations',
    'mg.benefit.stress.title': 'Stress & sleep',
    'mg.benefit.stress.text': 'Promotes nervous relaxation',
    'mg.table.title': 'Comparison of the most magnesium-rich waters',
    'mg.table.subtitle': 'Ranking from richest to least rich. Values are from the official labels of bottlers (mg/L).',
    'mg.table.water': 'Water',
    'mg.table.magnesium': 'Magnesium',
    'mg.table.calcium': 'Calcium',
    'mg.table.sodium': 'Sodium',
    'mg.table.type': 'Type',
    'mg.type.sparkling': 'Sparkling',
    'mg.type.still': 'Still',
    'mg.disclaimer.a': 'A water is considered ',
    'mg.disclaimer.b': 'magnesium-rich',
    'mg.disclaimer.c': ' from 50 mg/L (European regulation No. 1924/2006 on nutritional claims).',
    'mg.tips.title': 'How to choose your magnesium-rich water?',
    'mg.tips.1.h': '1. Also look at sodium',
    'mg.tips.1.p': 'Some highly mineralized waters (Saint-Yorre, Vichy Célestins) contain more than 1000 mg/L of sodium — nearly half a gram of salt per liter. To avoid in case of hypertension.',
    'mg.tips.2.h': '2. Alternate with lightly mineralized water',
    'mg.tips.2.p.a': 'Waters like ',
    'mg.tips.2.p.b': 'Hépar',
    'mg.tips.2.p.c': ' or ',
    'mg.tips.2.p.d': 'Contrex',
    'mg.tips.2.p.e': ' are effective in ',
    'mg.tips.2.p.f': '1 to 2 week cures',
    'mg.tips.2.p.g': ', alternating with a lighter water (Volvic, Mont Roucous, Evian) for daily use.',
    'mg.tips.3.h': '3. Check the quality of your tap water',
    'mg.tips.3.p.a': 'Before investing in bottled water, check the mineral content of ',
    'mg.tips.3.p.link': 'tap water in your town',
    'mg.tips.3.p.b': ' — it may already cover part of your needs.',
    'mg.faq.title': 'FAQ — Magnesium-rich waters',
    'mg.faq.q1.q': 'Which water is the richest in magnesium?',
    'mg.faq.q1.a': 'In France, Rozana is the natural mineral water containing the most magnesium (about 160 mg/L), followed closely by Hépar (119 mg/L). These two waters alone cover nearly 30% of the recommended daily intake (RDI) for magnesium with a single liter.',
    'mg.faq.q2.q': 'How much magnesium per day should an adult consume?',
    'mg.faq.q2.a': 'ANSES recommends 380 mg/day for an adult man and 300 mg/day for an adult woman. A liter of Hépar alone provides about 40% of these needs.',
    'mg.faq.q3.q': 'What are the benefits of magnesium-rich water?',
    'mg.faq.q3.a': 'Magnesium contributes to reducing fatigue, to the proper functioning of the nervous and muscular system, to electrolyte balance and to protein synthesis. Drinking mineralized water can supplement dietary intake in case of stress, intense sport or cramps.',
    'mg.faq.q4.q': 'Can you drink magnesium-rich water every day?',
    'mg.faq.q4.a': 'Yes, but with discernment. Highly mineralized waters such as Hépar or Contrex are not recommended as the only beverage: they are effective in occasional cures (1 to 2 weeks) or alternating with lightly mineralized water. People suffering from kidney failure or hypertension should consult their doctor.',
    'mg.faq.q5.q': 'Can tap water be rich in magnesium?',
    'mg.faq.q5.a': 'Most tap waters contain between 3 and 30 mg/L of magnesium — well below mineral waters. Check our map to know the exact content in your town.',
    'mg.cta.title': "Don't know which water to choose?",
    'mg.cta.body': 'Our personalized recommendation tool advises you based on your needs (fatigue, sport, pregnancy, hypertension...).',
    'mg.cta.button': 'Find my ideal water',
    'mg.hub.heading': 'Go further',
    'mg.hub.description': 'Additional resources to choose your water wisely.',
    'common.breadcrumb.home': 'Home',

