    'home.choose.title': 'Choosing your bottled water wisely',
    'home.choose.p1': 'Every bottled water has a <strong>unique mineral composition</strong>. Calcium, magnesium, bicarbonates… choosing the right water means matching it to your needs: <strong>babies</strong>, <strong>athletes</strong>, <strong>seniors</strong>.',
    'home.choose.p2': '<strong>pH</strong> and <strong>dry residue</strong> are key indicators. Lightly mineralized water suits daily use, while magnesium-rich water helps fight fatigue.',
    'home.choose.cta': 'See the water ranking →',
    'home.monitor.title': 'Monitor your water quality',
    'home.monitor.p1': 'Water quality data is public and accessible to all. With our diagnostic tool, retrieve the <strong>official analyses</strong> for your municipality in a few clicks.',
    'home.monitor.p2': 'Stay informed about limit exceedances, understand results, and receive <strong>real-time alerts</strong> to protect your health and that of your loved ones.',
    'home.monitor.cta': 'Start a free diagnostic →',
    'home.risks.title': 'Risks associated with tap water',
    'home.risks.p1': 'Tap water in France is generally of good quality, but it may contain traces of <strong>pesticides</strong>, <strong>microplastics</strong> or <strong>drug residues</strong> depending on the region.',
    'home.risks.p2': 'Old pipes may release <strong>lead</strong>, while chlorine treatment generates potentially undesirable by-products. Knowing your water quality is essential.',
    'home.risks.cta': 'Discover the pollutants →',

