    // ===== Filter pitcher comparison (cc.) =====
    'cc.tag': 'Home filtration',
    'cc.breadcrumb.guides': 'Guides',
    'cc.breadcrumb.current': 'Filter pitcher comparison',
    'cc.h1': 'Filter pitcher comparison: how to choose well',
    'cc.seo.title': 'Filter pitcher comparison: how to choose the right one',
    'cc.seo.desc': 'Filter pitchers compared on verifiable criteria: what they actually treat, the yearly cartridge cost, maintenance and their limits.',
    'cc.intro.p1': 'A filter pitcher mainly improves comfort: activated carbon captures residual chlorine and some of the organic compounds behind off-odours, while an ion-exchange resin temporarily reduces hardness, and therefore the feeling of limescale.',
    'cc.intro.p2': 'It does not make unsafe water drinkable. It does not remove nitrates, and its action on lead or other metals depends entirely on the cartridge type and its condition. A saturated cartridge can even degrade water quality.',
    'cc.intro.p3': 'Before buying, the first step is to know what your water actually contains: that is what determines whether a pitcher is enough, whether another technology is needed, or whether no device is required at all.',
    'cc.intro.cta.diag': 'Run my water diagnosis',
    'cc.intro.cta.quality': 'See my municipality analyses',
    'cc.intro.note': 'This page compares types of solutions and buying criteria, not brands. We hold no laboratory measurements per product and therefore publish no numeric performance figures by brand.',

    // Table
    'cc.table.title': 'Comparison by type of solution',
    'cc.table.intro': 'The ranges below are meant to position solutions relative to each other. They vary widely with the model, your water hardness and your consumption.',
    'cc.table.caption': 'Indicative orders of magnitude, brand-independent and excluding promotions.',
    'cc.table.col.type': 'Type of solution',
    'cc.table.col.treats': 'What it treats',
    'cc.table.col.cost': 'Cartridge cost over a year',
    'cc.table.col.maint': 'Maintenance',
    'cc.table.col.limits': 'Limits',
    'cc.row1.type': 'Standard filter pitcher',
    'cc.row1.treats': 'Chlorine taste and odour, part of the perceived limescale, some organic compounds.',
    'cc.row1.cost': 'Cartridge replaced roughly every 4 weeks: a few tens of euros per year depending on model and consumption.',
    'cc.row1.maint': 'Frequent rinsing and drying of the pitcher, storage in the fridge, replacement on schedule.',
    'cc.row1.limits': 'No guarantee on nitrates; action on metals varies with the cartridge; throughput limited to the pitcher volume.',
    'cc.row2.type': 'Long-life cartridge pitcher',
    'cc.row2.treats': 'Same main targets as a standard pitcher, with a cartridge rated for a longer lifespan.',
    'cc.row2.cost': 'Fewer cartridges per year but a higher unit price: the annual total is often in the same range.',
    'cc.row2.maint': 'Identical maintenance; the stated lifespan assumes lightly loaded water and normal use.',
    'cc.row2.limits': 'The advertised lifespan is theoretical: very hard water or heavy use shortens it.',
    'cc.row3.type': 'Tap-mounted filter',
    'cc.row3.treats': 'Taste and chlorine across the whole tap flow, and depending on the cartridge some particles and metals.',
    'cc.row3.cost': 'Cartridges usually cost more per unit but are replaced less often: a similar yearly budget, sometimes higher.',
    'cc.row3.maint': 'Checking the fitting and seal, flushing after a long absence, replacement on schedule.',
    'cc.row3.limits': 'Mechanical compatibility with the tap must be checked; reduced flow; no effect on nitrates unless a specific technology is used.',

    // How to choose
    'cc.choose.title': 'How to choose your filter pitcher',
    'cc.choose.intro': 'The purchase price of the pitcher is the least decisive criterion. The five points below are what make the difference in daily use.',
    'cc.choose.1.t': 'Capacity matched to the household',
    'cc.choose.1.d': 'A pitcher that is too small gets refilled constantly and eventually goes unused. Count the volume actually drunk each day by the household, not the volume printed on the box, which often includes the upper reservoir.',
    'cc.choose.2.t': 'The real cartridge cost over a year',
    'cc.choose.2.d': 'This is the expense that matters. Multiply the price of one cartridge by the number of recommended yearly replacements, adjusted to your consumption. A cheap pitcher with expensive refills costs more than a pricier one with affordable refills.',
    'cc.choose.3.t': 'A cartridge change indicator',
    'cc.choose.3.d': 'Even a basic indicator prevents the forgetfulness that is the main cause of poor filtration. Models counting filtered volume are more reliable than a simple day counter, but a calendar reminder does the job too.',
    'cc.choose.4.t': 'Certifications and standards',
    'cc.choose.4.d': 'Check that the manufacturer states precise normative references and the substances covered. A generic claim such as "purer water" carries no normative value. A certified reduction, by contrast, always names a specific substance.',
    'cc.choose.5.t': 'Ease of maintenance',
    'cc.choose.5.d': 'A pitcher that fully dismantles and is dishwasher safe will actually get cleaned. A model that is hard to open, with unreachable corners, will be neglected, which cancels out the benefit of filtering.',

    // Maintenance
    'cc.maint.title': 'Maintenance: the point that decides everything',
    'cc.maint.p1': 'A filter pitcher is a damp, lukewarm and stagnant environment. Poorly maintained, it can encourage bacterial growth and deliver water of lower quality than a plain glass from the tap.',
    'cc.maint.p2': 'Three habits are enough: clean the pitcher regularly with hot soapy water and dry it, keep filtered water in the fridge and drink it within the day, and above all respect the cartridge replacement interval stated by the manufacturer.',
    'cc.maint.p3': 'Past its lifespan a cartridge no longer filters: it releases. Sticking to the replacement schedule is the single most decisive criterion in this whole comparison, well ahead of the choice of model.',

    // FAQ
    'cc.faq.title': 'Frequently asked questions',
    'cc.faq.q1.q': 'Does a filter pitcher remove limescale?',
    'cc.faq.q1.a': 'It temporarily reduces hardness through an ion-exchange resin, which softens the feeling of limescale and the deposit in a kettle. It does not descale your plumbing and has no effect on the other taps. Limescale is not a health issue in any case: it is a domestic inconvenience.',
    'cc.faq.q2.q': 'Does a filter pitcher remove nitrates?',
    'cc.faq.q2.a': 'No, not as a general rule. Common activated-carbon and resin cartridges are not designed for nitrates. If your municipality shows high levels, a pitcher is not the right answer and you should look at a specific technology or a suitable bottled water.',
    'cc.faq.q3.q': 'Does a filter pitcher remove lead?',
    'cc.faq.q3.a': 'It depends entirely on the cartridge: some claim a lead reduction, others do not. Check that the substance is explicitly named by the manufacturer. Where lead pipes are present, the only lasting solution is replacing them, filtration being an interim measure.',
    'cc.faq.q4.q': 'How often should the cartridge be changed?',
    'cc.faq.q4.a': 'Follow the interval stated by the manufacturer, expressed in weeks or in litres treated. Very hard water or heavy consumption shortens it. Going past the deadline is the main risk: the cartridge saturates and can degrade the water instead of improving it.',
    'cc.faq.q5.q': 'Can filtered water be kept in the fridge?',
    'cc.faq.q5.a': 'Yes, and it is even recommended. Filtered water has lost part of the chlorine that limited microbial growth, so it keeps less well at room temperature. Store the pitcher covered in the fridge and drink the water within the day.',

